### Go 1.24+ Native TLS Hybrid Configuration
```go
package main

import (
    "crypto/tls"
    "net/http"
)

func main() {
    config := &tls.Config{
        MinVersion: tls.VersionTLS13,
        CurvePreferences: []tls.CurveID{
            tls.X25519MLKEM768, // Hybrid Post-Quantum Key Exchange
            tls.X25519,
        },
    }
    server := &http.Server{
        Addr:      ":8443",
        TLSConfig: config,
    }
    server.ListenAndServeTLS("cert.pem", "key.pem")
}
```

